// headings, buttons, labels, placeholders, badges and the task list switch the
// moment the language is changed. Long explanatory paragraphs, live backend
// data and engine-generated detail lines stay English in every language.
// Languages NOT listed fall back to English for these keys — their nav chrome
// still translates via DICT.
//
// Keys with {placeholders} are filled by the caller with .replace('{x}', …).

