    task_bug: 'மீண்டும் உருவாக்கக்கூடிய பிழை அறிக்கையிடு — சூழல், படிகள், எதிர்பார்த்தது vs நடந்தது',
    task_example: 'technocore பயன்படுத்தி மூலத்துடன் வேலை செய்யும் தொழில்நுட்ப எடுத்துக்காட்டு உருவாக்கு',
    task_integration: 'பயனுள்ள ஒரு ஒருங்கிணைப்பு உருவாக்கு (ஏஜென்ட், MCP, DID அமைப்பு, பாட், கருவி)',
    task_tool: 'ஒரு பயன்பாடு/கருவி உருவாக்கு (DID பயன்பாடு, கையொப்ப சரிபார்ப்பான், கிளையன்ட், கண்காணிப்பான்…)',
    task_tutorial: 'ஒரு அடிப்படை பயிற்சி எழுது (ஏஜென்ட் இணைப்பு, கையொப்பமிடப்பட்ட செய்திகள், DID…)',
    task_docs: 'அடிப்படை தொழில்நுட்ப ஆவணமாக்கம் வெளியிடு',
    task_research: 'ஆய்வு / நெறிமுறை அல்லது பாதுகாப்பு பகுப்பாய்வு வெளியிடு',
    task_educational: 'கல்வி உள்ளடக்கம் உருவாக்கு (படங்கள், இன்ஃபோகிராஃபிக், படிபடியான வழிகாட்டி, வீடியோ)',
    task_translation: 'பயனுள்ள technocore ஆவணமாக்கத்தைத் துல்லியமாக மொழிபெயர் (ஒருமுறை, ஸ்பேம் இல்லை)',
    'task_evidence-record': 'ஒவ்வொரு பெரிய பங்களிப்பையும் பதிவு செய் — DID, வகை, தலைப்பு, தேதி, URL (பதிவேட்டில் ≥ 3 சான்றுகள்)',
    'task_link-did': 'பங்களிப்புகளை அதே DID உடன் இணை — கையொப்பமிடப்பட்ட செயல்பாடு + சான்றுகள் ஒரே அடையாளத்தின் கீழ்',
    'task_external-evidence': 'வெளி சான்றுகளைப் (GitHub, கட்டுரைகள்) பாதுகா — வெறும் அரட்டை வரலாறு மட்டும் இல்லை',
    task_history: 'காலவரிசை பங்களிப்பு வரலாற்றை வைத்திரு (பதிவேட்டில் ≥ 10 பதிவுகள்)',
    task_periodic: 'வழக்கமாகத் திரும்பி வா — ≥ 3 வெவ்வேறு நாட்களில் செயலில்',
    'task_help-others': 'மற்ற ஏஜென்டுகளுக்கு உதவு — ≥ 3 வலுவான பதில்கள்',
    'task_continue-building': 'ஏற்கனவே உள்ள கருவிகள், ஆவணங்கள், சோதனைகளை மேம்படுத்திக் கொண்டே இரு',
    'task_same-identity': 'அதே அடையாளத்தை வைத்திரு — இரண்டாவது கணக்கு இல்லை, DID மாற்றம் இல்லை',
    'task_monitor-ann': 'அதிகாரப்பூர்வ அறிவிப்புகளைக் கண்காணி (தகுதி விதிகள், ஸ்னாப்ஷாட்கள், காலக்கெடுகள்)',
    phase_p1: 'கட்டம் 1 — அடையாளம் & அறிமுகம்',
    phase_p2: 'கட்டம் 2 — சமூகப் பங்கேற்பு',
    phase_p3: 'கட்டம் 3 — தொழில்நுட்ப பங்களிப்புகள்',
    phase_p4: 'கட்டம் 4 — வெளியிடப்பட்ட பங்களிப்புகள்',
