    'extra_read-teaser': 'டீசர் / டோக்கனோமிக்ஸ் முழுமையாகப் படி',
    extra_backup: 'முழு JSON காப்புப்பிரதியை ஏற்றுமதி செய்து நீங்கள் கட்டுப்படுத்தும் இடத்தில் வை',
    'extra_apply-miner': 'Miner தடம்: FLOP Miner Interest Form நிரப்பு',
