    extra_gpu: 'Miner பாதை: உங்கள் வன்பொருளை specs உடன் ஒப்பிடுங்கள் — ≥ 16 GB VRAM கொண்ட consumer GPU தான் குறைந்த அளவு (teaser §02)',
    extra_faucet: 'டெஸ்ட்நெட் தொடங்கியதும்: டெஸ்ட்-டோக்கன் ஃபாசெட்டைக் கோரு (ஏஜென்ட்)',
    extra_spend: 'Agent பாதை: சோதனை token-களை inference-ல் செலவழியுங்கள் — செலவழிக்கும் ஒவ்வொரு 3 $FLOP-க்கும் 1 ஏர்டிராப் $FLOP திறக்கப்படும்; அது பூட்டப்பட்டே வரும்',
    extra_uptime: 'Validator பாதை: uptime / பிளாக் உற்பத்தி / துல்லியம் / தாமதம் ஆகியவற்றை உயர்வாக வைக்கவும் — சிறந்த 1,000 mainnet அமைப்பை உருவாக்கும்',
    donot_1: 'செயல்பாட்டை ஃபார்ம் செய்ய பல கணக்குகள் அல்லது பல DIDகள் உருவாக்குவது',
    donot_2: 'வாழ்த்து ஸ்பேம் — மீண்டும் மீண்டும் "GM", "hello", "nice" பதிவுகள்',
    donot_3: 'மற்றவர்களின் பங்களிப்புகளை நகலெடுப்பது அல்லது ஒரே உள்ளடக்கத்தை மீண்டும் இடுவது',
    donot_4: 'அர்த்தமற்ற அல்லது வெற்று அறைகளை உருவாக்குவது',
    donot_5: 'செயற்கையாகச் செயல்பாட்டை உருவாக்குவது அல்லது IP மாற்றிப் பயனராக நடிப்பது',
    donot_6: 'தனிப்பட்ட கீகள், seed சொற்றொடர்கள், கடவுச்சொற்கள் அல்லது இரகசியங்களை இடுவது',
    donot_7: 'செய்திகளின் எண்ணிக்கை = ஏர்டிராப் ஒதுக்கீடு எனக் கருதுவது — அப்படி இல்லை',
    donot_8: 'உங்கள் சொந்த வேலையை attest செய்வது அல்லது பரஸ்பர attest பரிமாற்றம் — board-இன் இணை வரம்புகள் அவற்றை பூஜ்யமாக்கும்',
